CREATE TABLE `citizen_resolution_feedback` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reportId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolutionSubmissionId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reporterId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `decision` enum('CONFIRMED','DISPUTED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `citizen_resolution_feedback_resolutionSubmissionId_key` (`resolutionSubmissionId`),
  KEY `citizen_resolution_feedback_reportId_createdAt_idx` (`reportId`,`createdAt`),
  KEY `citizen_resolution_feedback_reporterId_idx` (`reporterId`),
  CONSTRAINT `citizen_resolution_feedback_reporterId_fkey` FOREIGN KEY (`reporterId`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `citizen_resolution_feedback_reportId_fkey` FOREIGN KEY (`reportId`) REFERENCES `civic_report` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `citizen_resolution_feedback_resolutionSubmissionId_fkey` FOREIGN KEY (`resolutionSubmissionId`) REFERENCES `resolution_submission` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
