CREATE TABLE `civic_report` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trackingId` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submissionKey` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reporterId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `barangay` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `address` varchar(300) COLLATE utf8mb4_unicode_ci NOT NULL,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `locationSource` varchar(12) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ADDRESS',
  `gpsAccuracy` double DEFAULT NULL,
  `status` enum('SUBMITTED','UNDER_REVIEW','IN_PROGRESS','PENDING_VERIFICATION','RESOLVED','REJECTED','REOPENED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SUBMITTED',
  `assignedOffice` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `assignedStaffId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `priority` enum('LOW','NORMAL','HIGH','URGENT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NORMAL',
  PRIMARY KEY (`id`),
  UNIQUE KEY `civic_report_trackingId_key` (`trackingId`),
  UNIQUE KEY `civic_report_reporterId_submissionKey_key` (`reporterId`,`submissionKey`),
  KEY `civic_report_reporterId_createdAt_idx` (`reporterId`,`createdAt`),
  KEY `civic_report_status_createdAt_idx` (`status`,`createdAt`),
  KEY `civic_report_assignedOffice_assignedStaffId_status_idx` (`assignedOffice`,`assignedStaffId`,`status`),
  KEY `civic_report_priority_createdAt_idx` (`priority`,`createdAt`),
  KEY `civic_report_assignedStaffId_fkey` (`assignedStaffId`),
  CONSTRAINT `civic_report_assignedStaffId_fkey` FOREIGN KEY (`assignedStaffId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `civic_report_reporterId_fkey` FOREIGN KEY (`reporterId`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
