CREATE TABLE `community_survey_revision` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `actorId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `surveyYear` int NOT NULL,
  `revision` int NOT NULL,
  `action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `schemaVersion` int NOT NULL DEFAULT '2',
  `requestKey` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `payloadHash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resultVersion` int NOT NULL,
  `answersJson` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `community_survey_revision_userId_requestKey_key` (`userId`,`requestKey`),
  UNIQUE KEY `community_survey_revision_userId_surveyYear_revision_key` (`userId`,`surveyYear`,`revision`),
  KEY `community_survey_revision_userId_surveyYear_createdAt_idx` (`userId`,`surveyYear`,`createdAt`),
  KEY `community_survey_revision_actorId_fkey` (`actorId`),
  CONSTRAINT `community_survey_revision_actorId_fkey` FOREIGN KEY (`actorId`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `community_survey_revision_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
