CREATE TABLE `job_opportunity` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employer` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sector` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `workType` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `barangay` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `skillsJson` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `interestsJson` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `education` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contactInfo` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL,
  `externalUrl` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('DRAFT','PENDING_REVIEW','RETURNED','PUBLISHED','CLOSED','FILLED','ARCHIVED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `expiresAt` datetime(3) DEFAULT NULL,
  `publishedAt` datetime(3) DEFAULT NULL,
  `createdById` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `version` int NOT NULL DEFAULT '1',
  `reviewSource` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewRequestedAt` datetime(3) DEFAULT NULL,
  `reviewedAt` datetime(3) DEFAULT NULL,
  `reviewedById` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewNote` text COLLATE utf8mb4_unicode_ci,
  `employerVerified` tinyint(1) NOT NULL DEFAULT '0',
  `vacancyVerified` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `job_opportunity_status_publishedAt_idx` (`status`,`publishedAt`),
  KEY `job_opportunity_sector_workType_idx` (`sector`,`workType`),
  KEY `job_opportunity_createdById_fkey` (`createdById`),
  KEY `job_opportunity_reviewedById_idx` (`reviewedById`),
  CONSTRAINT `job_opportunity_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `job_opportunity_reviewedById_fkey` FOREIGN KEY (`reviewedById`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
