CREATE TABLE `jobseeker_profile` (
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `skillsJson` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `interestsJson` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `education` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `preferredArea` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `availability` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`userId`),
  CONSTRAINT `jobseeker_profile_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ELB-DEMO-STATEMENT
CREATE TABLE `notification` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `userId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(48) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(180) COLLATE utf8mb4_unicode_ci NOT NULL,
  `message` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `href` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `readAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `notification_userId_readAt_createdAt_idx` (`userId`,`readAt`,`createdAt`),
  KEY `notification_module_createdAt_idx` (`module`,`createdAt`),
  CONSTRAINT `notification_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
