CREATE TABLE `work_assignment` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `module` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entityType` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `entityId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `department` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assignedStaffId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN',
  `claimDeadline` datetime(3) DEFAULT NULL,
  `acceptedAt` datetime(3) DEFAULT NULL,
  `declinedAt` datetime(3) DEFAULT NULL,
  `completedAt` datetime(3) DEFAULT NULL,
  `attemptCount` int NOT NULL DEFAULT '0',
  `lastOfferedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `work_assignment_module_entityType_entityId_key` (`module`,`entityType`,`entityId`),
  KEY `work_assignment_assignedStaffId_status_claimDeadline_idx` (`assignedStaffId`,`status`,`claimDeadline`),
  KEY `work_assignment_module_department_status_createdAt_idx` (`module`,`department`,`status`,`createdAt`),
  CONSTRAINT `work_assignment_assignedStaffId_fkey` FOREIGN KEY (`assignedStaffId`) REFERENCES `user` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
